import re

from moler.exceptions import ParsingDone
from ta_moler.cmd.rtg.ws.genericrtgws import GenericRtgWs

__author__ = 'Dawid Gwizdz'
__copyright__ = 'Copyright (C) 2019-2020, Nokia'
__email__ = 'dawid.gwizdz@nokia.com'


class RtgPcapStop(GenericRtgWs):
    """Command for stopping rtg-pcap script."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Rtg pcap stop command. Should be executed after rtg_pcap_start command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(RtgPcapStop, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return 'STOP'

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_captured_to(line)
            except ParsingDone:
                pass
        return super(RtgPcapStop, self).on_new_line(line, is_full_line)

    # Example line: Captured to /home/rtg/logs/pcaps/rtg_wireshark.tar.gz
    _re_captured_to = re.compile(r'Captured to (?P<OUTPUT_LOG_FILE>.*)')

    def _parse_captured_to(self, line):
        """
        Parse line containing captured info.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_captured_to, line):
            self.current_ret['OUTPUT_LOG_FILE'] = self._regex_helper.search(
                self._re_captured_to, line).group('OUTPUT_LOG_FILE')
            self.current_ret['OUTPUT_LOG_DIR'] = self.current_ret['OUTPUT_LOG_FILE'][:-7]
            raise ParsingDone


